import {story,lessons,courseSchedule,courseTitle} from './course.mjs';
import {sources,caseFile,fieldDictionary,parameters} from './case-source.mjs';
import {effect,economics,metricValue,samplePlan,allocationCheck,submissionState} from './investigation.mjs';
import {esc,num,pct,pp,usd,stat,empty,rateChart,effectChart,attributionChart,moneyChart,explorationChart} from './charts.mjs';
const link=(url,text)=>`<a href="${url}" target="_blank" rel="noreferrer">${text} ↗</a>`;
const pageHead=(eyebrow,title,description)=>`<div class="page-head"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>`;
const panel=(title,body,cls='')=>`<section class="panel ${cls}"><h3>${title}</h3>${body}</section>`;
const note=(text,type='')=>`<div class="callout ${type}">${text}</div>`;
const selected=(x,y)=>x===y?' selected':'';
const currentGroup=s=>s.groups.find(g=>g.id===s.groupId)||s.groups[0];
const stateLabel={draft:'尚未提交',current:'证据有效',stale:'口径或前题已变更 · 请重新提交'};
export function storyView(s){const e=effect(s.summary),d=s.summary?.usable?s.summary:null;
 return `<section class="story-hero"><div class="hero-copy"><span class="eyebrow">01 / 案例故事 · 15 MIN</span><span class="case-badge">BERKELEY HAAS · ROCKET FUEL</span><h1>广告，究竟带来了<br><em>多少增量？</em></h1><p>${story.intro}</p><a class="button primary" href="#mission">进入这场客户会议 <span>↗</span></a><div class="hero-meta"><span>120 分钟</span><span>4 道连贯大题</span><span>问题与答案同时开放</span></div></div><div class="hero-board"><div class="board-top"><span>CLIENT REVIEW</span><span class="status-light">试投复盘</span></div><h2>有购买，<br>就说明广告有效吗？</h2><div class="board-flow"><div><span>品牌与自然需求</span><b>本来也会购买？</b></div><i>＋</i><div class="active"><span>商业广告</span><b>多带来了购买？</b></div><i>↓</i><div class="result"><span>我们观察到的结果</span><b>购买发生了</b></div></div><div class="board-foot">缺少对照时，这两部分无法分开。</div></div></section>
 <div class="section-heading"><div><span class="eyebrow">THE BUSINESS DILEMMA</span><h2>客户真正需要回答的，<br>是三个相连的经营问题。</h2></div><p>${story.dilemma}</p></div>
 <div class="three-col dilemma-cards"><article><span class="number">01</span><h3>归因困境</h3><p>购买可能由既有需求与广告共同产生。单看广告组购买量，会把本来就会发生的购买算给广告。</p><span>需要：一个可信的反事实</span></article><article><span class="number">02</span><h3>价值困境</h3><p>即便广告提高购买概率，增量贡献仍需覆盖成本。PSA 对照同样消耗广告位，测量有代价。</p><span>需要：统一的增量经济口径</span></article><article><span class="number">03</span><h3>优化困境</h3><p>频次和时段出现差异，可能来自人群与机会差异。一次试投的平均效果，也不能保证扩大预算后的回报。</p><span>需要：下一轮可验证的策略</span></article></div>
 <div class="section-heading"><div><span class="eyebrow">WHAT THE FILE TELLS US</span><h2>先看全貌，再引入对照。</h2></div><p>以下数字由当前 CSV 直接汇总。人数是用户数，曝光是累计次数，两者不能混作同一个分母。</p></div>
 <div class="stats three-col">${stat('活动中的用户',num(d?.all.users),'一行一个用户')}${stat('累计广告位曝光',num(d?.all.impressions),'商业广告 + PSA')}${stat('购买用户',num(d?.all.conversions),'发生购买，不等于广告带来')}</div>
 <div class="two-col">${panel('怎样把“本来会买”分出来？',`<p>案例以用户随机分配商业广告与 PSA。对照组也会出现购买，其转化率帮助估计缺少商业广告时的基线。</p>${rateChart(s.summary)}`)}${panel('相同的购买结果，可以有不同解释',`${attributionChart(s.summary)}<p class="answer-text">${e?`广告组 ${num(s.summary.arms[1].conversions)} 位购买用户中，估计 ${num(e.baseline,1)} 位在 PSA 条件下也会购买。其余差值才是本次实验估计的增量。`:'载入数据后，将把广告组购买拆成反事实基线与估计增量。'}</p><a href="#q2">到第 2 题逐步推导 ↗</a>`)}</div>
 ${note(`${story.context}<br><small>${story.origin} ${link(sources.official,'官方案例')} · ${link(sources.course,'作者课程记录')}</small>`)}
 <a class="next-card" href="#mission"><span>接下来 · 本节课做什么</span><strong>把经营问题变成四份可交付的分析 ↗</strong></a>`;
}
export function missionView(){return `${pageHead('02 / 本节课的任务 · 10 MIN','从一份报表，走到一个决策。','你们将扮演客户与投放方共同组成的分析小组：先建立衡量标准，再验证增量，最后给出经营建议与下一轮实验。')}
 <div class="mission-chain">${lessons.map(l=>`<a href="#${l.id}"><span>${l.n}</span><h3>${l.short}</h3><p>${l.deliverable}</p><b>${l.time} MIN ↗</b></a>`).join('')}</div>
 <div class="two-col">${panel('课堂怎样进行',`<p>建议每组 3–5 人，分别承担业务决策、指标定义、实验分析与质疑复核角色。先阅读完整问题，在平台计算和比较，再提交本组结论。</p><p>每题的参考答案和推导始终可见。独立初判与证据提交是练习工具；不同结论只要口径一致、证据充分，都值得讨论。</p><p>第 4 题之后留出 10 分钟答辩：用一条因果证据、一张经营核算和一个实验方案，回应另一组的质疑。</p>`)}${panel('经营分析的边界',`<p>本课覆盖目标 → 指标 → 实验投放复盘 → 增量测量 → 经济评价 → 下一轮设计的经营闭环。</p><p>六列用户实验数据没有素材制作记录、逐次竞价、点击、订单金额与退款。相关指标需要另行采集；不会补造这些记录来假装覆盖全流程明细。</p><a href="#data">先确认字段和原始数据 ↗</a>`)}</div>
 ${panel('120 分钟课程路线',`<div class="schedule">${courseSchedule.map(([t,n,a])=>`<div><time>${t}</time><b>${n}</b><span>${a}</span></div>`).join('')}</div>`)}
 ${panel('四题怎样对应既有案例',`<div class="table-scroll"><table><thead><tr><th>本课任务</th><th>既有材料依据</th><th>本课增加的教学设计</th></tr></thead><tbody><tr><td>01 指标体系</td><td>原案例的效果与经济回报问题</td><td>可计算定义、分组共创、数据缺口</td></tr><tr><td>02 因果验证</td><td>原题 1：是否带来额外购买</td><td>质量检查、95% 区间、识别条件</td></tr><tr><td>03 经营决策</td><td>原题 2：成本、回报、对照代价</td><td>增量净贡献、盈亏边界、条件建议</td></tr><tr><td>04 下一轮实验</td><td>原题 3–4：频次/时段、下一轮投放</td><td>把探索现象写成预先设计的随机实验</td></tr></tbody></table></div><p class="muted">题目为中文教学改编，参考答案由本课程方法与当前数据计算得出，未声称是出版方答案。</p>`)}<a class="next-card" href="#q1"><span>开始第一份交付</span><strong>定义你们自己的指标体系 ↗</strong></a>`;}
export function dataView(s){const d=s.summary,m=s.meta;
 return `${pageHead('DATA / 数据集与原始明细','先认识数据，再开始分析。','Rocket Fuel 教学案例的用户级实验数据。原始单元格与 CSV 物理行号保留，汇总和推断由这份文件计算。')}
 <section class="dataset-card"><div><span class="pill">案例配套 CSV · 公开镜像</span><h2>rocketfuel_data.csv</h2><p>来源：OguzhanCetinkaya/rocketfuel 的固定版本。官方案例页确认有同名配套数据；镜像未与付费官方文件逐字节认证。</p><div class="button-row"><button class="primary" data-action="load-mirror" ${s.busy?'disabled':''}>从公开镜像加载</button><button data-action="import-csv" ${s.busy?'disabled':''}>导入案例 CSV</button><button data-action="load" ${s.busy?'disabled':''}>重新读取环境数据</button><a class="button" href="${caseFile.url}" target="_blank" rel="noreferrer">打开镜像原始 CSV ↗</a>${m?.source==='local'?`<a class="button" href="${caseFile.local}" download>下载环境原始 CSV ↓</a>`:''}</div></div><div class="dataset-spec"><strong>${num(d?.audit.rows??caseFile.rows)}</strong><span>${d?'当前文件记录':'来源文件记录'} · 6 列 · ${(caseFile.bytes/1024/1024).toFixed(2)} MiB</span><small>${parameters.period}<br>活动期来自案例，CSV 没有日期列</small></div></section>
 ${s.loadError?note(esc(s.loadError),'warning'):''}
 ${s.busy?note('正在加载并核验完整数据，请稍候…'):''}
 ${!m?panel('换一个环境，怎样载入数据？',`<p>数据文件不随代码或 dist 分发。Node 环境使用 <code>npm start</code> 会先准备数据；也可单独运行 <code>npm run data:download</code>。</p><p>只有静态网页时，点击“从公开镜像加载”，浏览器会下载固定版本并核验 SHA-256。网络受限时，打开上方 CSV 链接并将文件保存到 <code>data/private</code>，再点击“导入案例 CSV”。</p><p class="muted">镜像加载约 11.47 MiB，只在当前浏览器内计算，不会保存到环境目录或上传文件；刷新页面后需重新加载。静态模式下，小组 JSON、报告与明细导出仍需配套 Node 服务。</p>`):''}
 ${m?note(`当前：${esc(m.filename)} · ${num(m.bytes)} 字节 · ${m.hash===caseFile.sha256?'文件指纹与固定镜像一致':'导入文件与固定镜像不同，结果仅代表当前文件'}<br><code class="hash">SHA-256 ${m.hash}</code>`):note('尚未载入数据。方法与答案文本仍可阅读；数值不会用示例数据代替。')}
 <div class="two-col">${panel('一行究竟是什么',`<p>一名被 Cookie 标识的用户在活动期内的汇总。test 是实验组别，converted 是是否购买，曝光数量与主要曝光时段为活动结束后的汇总。</p><p>案例材料允许为教学与保密修改数值。本项目不自行生成经营数据，不把镜像认证为官方原件。</p>`)}${panel('这张表回答不了什么',`<p>没有点击、逐笔收入、订单数、退款或逐日成本。不能计算实测 CTR、ROAS、完整净利润，也不能重建购买时间。</p><p>没有随机分配日志、投放前画像与失访名单。因果推断依赖案例描述的随机化及完整追踪前提。</p>`)}</div>
 ${panel('字段字典',`<div class="table-scroll"><table><thead><tr><th>原始字段</th><th>含义</th><th>口径与边界</th><th>类型</th></tr></thead><tbody>${fieldDictionary.map(f=>`<tr><td><code>${f[0]}</code></td><td>${f[1]}</td><td>${f[2]}</td><td><span class="pill">${f[3]}</span></td></tr>`).join('')}</tbody></table></div>`)}
 ${panel('文件质量检查',d?`<div class="stats three-col">${stat('重复用户 ID',num(d.audit.duplicateIds),'不静默去重')}${stat('异常记录',num(d.audit.invalidRows),'保留源行供检查')}${stat('空单元格',num(d.audit.missingCells),'空值不当作 0')}</div>${note(d.usable?'结构检查通过，可以计算。通过不代表所有实验前提都已验证。':'当前数据不足以推断：存在异常记录、缺少某组或没有有效用户。数值答案已暂停。',d.usable?'':'warning')}<p>曝光最小 / 最大值：${num(d.audit.minimumImpressions)} / ${num(d.audit.maximumImpressions)}。通过单行校验的用户数（质量异常时仅供诊断）：PSA ${num(d.arms[0].users)}，商业广告 ${num(d.arms[1].users)}。</p>${d.issues.length?`<ul>${d.issues.slice(0,10).map(x=>`<li>第 ${x.line} 行：${x.errors.join('；')}</li>`).join('')}</ul><p>这里只列前 10 条；可在明细中筛选所有异常行。</p>`:''}`:empty())}
 <section class="panel" id="raw-data"><div class="panel-heading"><div><span class="eyebrow">RAW DATA EXPLORER</span><h3>直接看见原始明细</h3></div><button data-action="export-raw" ${!d?'disabled':''}>导出筛选明细 ↓</button></div><form id="raw-form" class="raw-filters"><label>实验组别<select name="arm"><option value="">全部用户</option value="1"${selected(s.filters.arm,'1')}>商业广告 · 1</option><option value="0"${selected(s.filters.arm,'0')}>PSA · 0</option></select></label><label>是否购买<select name="converted"><option value="">全部结果</option><option value="1"${selected(s.filters.converted,'1')}>已购买 · 1</option><option value="0"${selected(s.filters.converted,'0')}>未购买 · 0</option></select></label><label class="grow">搜索原始值或源行号<input name="query" value="${esc(s.filters.query)}" placeholder="例如用户 ID"></label><label class="checkbox"><input type="checkbox" name="onlyIssues" ${s.filters.onlyIssues?'checked':''}>仅异常行</label><button type="submit" class="primary" ${!d?'disabled':''}>筛选</button></form><div id="raw-results">${rawResults(s.raw)}</div><p class="muted">单元格保持源文件字符值。源行号包含第 1 行表头；筛选与分页不会重排源行。导出额外添加 source_row，原始下载保留原文件。</p></section>
 <a href="#sources">查看来源记录、固定版本和复现方法 ↗</a>`;
}
export function rawResults(r){if(!r)return empty();return `<div class="table-scroll"><table class="raw-table"><thead><tr><th>源行号</th>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr><td>${row.line}</td>${row.cells.map(c=>`<td class="raw-cell">${esc(c)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">没有匹配的原始记录</td></tr>'}</tbody></table></div><div class="pagination"><span>匹配 ${num(r.total)} 行 · 第 ${r.page+1} / ${r.pages} 页 · 每页 30 行</span><div><button data-action="raw-prev" ${r.page===0?'disabled':''}>上一页</button><button data-action="raw-next" ${r.page===r.pages-1?'disabled':''}>下一页</button></div></div>`;}
export function metricBoard(s){const g=currentGroup(s);return `<div class="metric-tree">${['结果','过程','护栏'].map(role=>`<section><div class="tree-role">${role}指标</div>${g.metrics.filter(m=>m.role===role).map(m=>{let v;try{v=metricValue(m.formula,s.summary,m.population);}catch{return `<p>指标 ${esc(m.name)} 需重新检查</p>`;}return `<article class="metric-node"><span>${esc(m.name)}</span><strong>${formatMetric(v.value,m.unit)}</strong><code>${esc(m.formula)}</code><small>${v.fields.map(esc).join(' + ')} → ${esc(m.unit)} · ${populationLabel(m.population)}</small><p>${esc(m.meaning)}</p><small>窗口：${esc(m.window)}</small><button class="text-button" data-action="edit-metric" data-id="${esc(m.id)}">编辑定义</button></article>`;}).join('')||'<p class="placeholder">等待本组定义</p>'}</section>`).join('')}</div>`;}
function populationLabel(p){return {all:'全部用户',treatment:'商业广告组',control:'PSA 组'}[p]||'未知人群';}
function formatMetric(v,u){return u==='%'?pct(v,3):u==='百分点'?pp(v,3):num(v,3)+(u==='人数'?' 人':u==='次'?' 次':u==='次/人'?' 次/人':'');}
function referenceMetrics(s){const d=s.summary,e=effect(d);if(!e)return panel('一份可核算的参考指标体系',empty());return panel('一份可核算的参考指标体系',`<div class="metric-reference-flow"><span>经营目标：可持续的增量净贡献</span><b>↓</b><strong>结果：商业广告 − PSA 的用户转化率差 ${pp(e.delta)}</strong><b>↙　　↘</b><span>过程：曝光规模与人均频次　｜　护栏：分流与数据质量</span></div><div class="table-scroll"><table><thead><tr><th>参考指标</th><th>角色 / 单位</th><th>可执行公式</th><th>商业广告组</th><th>PSA 组</th></tr></thead><tbody><tr><td>用户转化率</td><td>结果 / %</td><td><code>SUM(converted) / COUNT(user_id)</code></td><td>${pct(e.pt,3)}</td><td>${pct(e.pc,3)}</td></tr><tr><td>人均曝光</td><td>过程 / 次/人</td><td><code>SUM(tot_impr) / COUNT(user_id)</code></td><td>${num(d.arms[1].impressions/d.arms[1].users,3)}</td><td>${num(d.arms[0].impressions/d.arms[0].users,3)}</td></tr><tr><td>入组人数</td><td>护栏 / 人</td><td><code>COUNT(user_id)</code></td><td>${num(d.arms[1].users)}</td><td>${num(d.arms[0].users)}</td></tr></tbody></table></div><p class="muted">均按整个活动期计算；这是本课参考口径，不会自动写入或替换本组指标。差值可用 T(MEAN(converted)) − C(MEAN(converted)) 定义，95% 区间见第 2 题。</p>`);}
export function metricsWorkbench(s){const g=currentGroup(s),m=s.metricDraft||{name:'',formula:'',unit:'%',role:'结果',population:'all',window:'整个案例活动期',meaning:''};
 return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">METRIC STUDIO</span><h3>本组的指标，由你们定义。</h3></div><span class="pill">${esc(g.name)} · ${g.metrics.length} 个指标</span></div><p>输入公式即可计算。支持 COUNT(user_id)、SUM(converted)、SUM(tot_impr)、MEAN(converted)、MEAN(tot_impr) 与四则运算。T(公式) 固定商业组、C(公式) 固定 PSA 组，可跨组求差。百分比或百分点单位会将比值 ×100 显示，公式无需再乘 100。</p><div class="preset-row"><span>从一个口径开始：</span><button data-action="preset" data-kind="conversion">用户转化率</button><button data-action="preset" data-kind="frequency">人均曝光</button><button data-action="preset" data-kind="users">入组人数</button><button data-action="preset" data-kind="increment">增量转化率</button></div><form id="metric-form"><input type="hidden" name="id" value="${esc(m.id||'')}"><div class="form-grid"><label>指标名称<input name="name" required maxlength="80" value="${esc(m.name)}" placeholder="给指标一个清晰的名称"></label><label>指标角色<select name="role">${['结果','过程','护栏'].map(v=>`<option${selected(v,m.role)}>${v}</option>`).join('')}</select></label><label class="span-2">计算公式<input class="formula-input" name="formula" required value="${esc(m.formula)}" placeholder="SUM(converted) / COUNT(user_id)"></label><label>显示单位<select name="unit">${['%','百分点','人数','次','次/人','数值'].map(v=>`<option${selected(v,m.unit)}>${v}</option>`).join('')}</select></label><label>统计人群<select name="population">${['all','treatment','control'].map(v=>`<option value="${v}"${selected(v,m.population)}>${populationLabel(v)}</option>`).join('')}</select></label><label>观察窗口<input name="window" required maxlength="150" value="${esc(m.window)}"></label><label>业务用途<input name="meaning" required maxlength="300" value="${esc(m.meaning)}" placeholder="它支持什么判断？"></label></div><div class="form-footer"><span id="metric-preview" role="status">填写公式，即时检查口径与结果</span><button type="submit" class="primary">${m.id?'保存新的定义版本':'加入本组指标体系'} ＋</button></div></form><div id="metric-board">${metricBoard(s)}</div><p class="muted">修改定义会保留版本，并使已有证据标记为待更新；原有文字不会被清除。此处的时间窗口用于口径说明，CSV 只能按整个活动期计算。</p></section>`;
}
function auditView(s){const d=s.summary,a=allocationCheck(d);if(!d)return empty();if(!d.usable)return note('基础质量检查未通过：暂停分流与因果解释。请在数据页定位原始异常行。','warning');return `<div class="stats three-col">${stat('PSA 占比',pct(a?.observed,4),'案例预设 4%')}${stat('重复 / 异常行',`${num(d.audit.duplicateIds)} / ${num(d.audit.invalidRows)}`,'结构校验')}${stat('分流检查',a?.flag?'存在偏离信号':'未发现明显偏离','双侧阈值 α = 0.001')}</div><p>以计划比例 4% 计算的分流标准化偏差 z = ${num(a?.z,4)}。组别人数不能证明随机化成功；缺失分流日志和投放前画像，其他实验前提只能依据案例说明。</p>`;}
function q2Answer(s){const d=s.summary,e=effect(d);return `${auditView(s)}${e?`<div class="two-col">${rateChart(d)}<div class="result-box"><span>商业广告 − PSA</span><strong>${pp(e.delta)}</strong><p>相对提升 ${pct(e.lift,2)}，分母是 PSA 转化率。</p><p>95% 区间<br><b>[${pp(e.ci[0])}, ${pp(e.ci[1])}]</b></p></div></div>${effectChart(d)}${attributionChart(d)}${note(e.ci[0]>0?'在随机化与追踪前提成立时，95% 区间高于 0，支持商业广告相对 PSA 提高了本次活动的购买概率。':e.ci[1]<0?'当前区间低于 0，支持商业广告相对 PSA 降低了购买概率。':'当前区间包含 0，证据不足以排除无差异；这不等于证明没有效果。')}`:empty('当前没有可用于推断的数据；请先载入并解决数据质量问题。')}`;}
export function economicsResult(s){const g=currentGroup(s),e=economics(s.summary,g.scenario);if(!e)return empty();return `<div class="stats three-col">${stat('估计增量购买',num(e.incremental,1),'Δ × 广告组人数')}${stat('增量净贡献',usd(e.net),'扣除选定范围的投放费')}${stat('增量 ROI',pct(e.roi,2),'增量净贡献 / 投放费')}</div>${moneyChart(e)}<div class="calculation-lines"><p><span>增量贡献</span><code>${num(e.incremental,4)} × ${usd(e.margin)} = ${usd(e.contribution)}</code></p><p><span>投放成本</span><code>${num(e.impressions)} ÷ 1,000 × ${usd(e.cpm)} = ${usd(e.cost)}</code></p><p><span>条件 95% 净贡献区间</span><code>[${usd(e.netCI[0])}, ${usd(e.netCI[1])}]</code></p><p><span>盈亏 CPM / 单位贡献</span><code>${usd(e.breakEvenCPM)} / ${usd(e.breakEvenMargin)}</code></p></div>${note(e.netCI[0]>0?'在固定成本与单位贡献参数下，净贡献区间整体为正。可支持受控延续；扩大预算仍需验证边际效果。':e.netCI[1]<0?'在当前参数下，净贡献区间整体为负。需要调整策略或成本，并用新实验验证。':'净贡献区间跨越 0；即使点估计为正，也应把经济性不确定性带入决策。')}<p class="muted">上述区间仅传播转化率差的不确定性；不包含 CPM、单位贡献的估计误差。若直接把广告组全部购买乘单位贡献，会得到 ${usd(e.naive)}，其中包含 PSA 基线购买的价值。</p>`;}
function economicsWorkbench(s){const g=currentGroup(s),p=g.scenario;return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">DECISION LAB</span><h3>把效果，换算成经营价值。</h3></div><span class="pill" id="scenario-label">${p.cpm===9&&p.margin===40&&p.scope==='pilot'?'案例参数 · 整个试投':'学员敏感性情景'}</span></div><p>案例给定 CPM $9、每转化用户贡献约 $40。默认评价整个试投，包含 PSA 的曝光费。改变输入后仅表示条件敏感性分析，不会修改原始数据。</p><form id="economic-form" class="scenario-form"><label>CPM · 美元 / 千次<input type="number" name="cpm" min="0" step="0.1" value="${p.cpm}" required></label><label>单位贡献 · 美元 / 购买用户<input type="number" name="margin" min="0" step="0.1" value="${p.margin}" required></label><label>成本范围<select name="scope"><option value="pilot"${selected(p.scope,'pilot')}>整个试投（广告 + PSA）</option><option value="treatment"${selected(p.scope,'treatment')}>仅商业曝光（替代范围）</option></select></label><button type="submit" class="primary">更新核算</button></form><div id="economic-result">${economicsResult(s)}</div></section>`;}
export function plannerResult(s){const g=currentGroup(s),p=g.plan,e=effect(s.summary),baseline=p.baseline==='psa'?e?.pc:e?.pt,plan=samplePlan({baseline,mdePP:p.mdePP,controlShare:p.controlShare,dailyUsers:p.dailyUsers});if(!plan)return note('填写大于 0 的 MDE（百分点），并载入有效实验数据后计算样本量。MDE 应由业务价值决定，不能为追求显著性随意调小或调大。');return `<div class="stats three-col">${stat('候选策略组',num(plan.treatment),'计划样本，不是实际观测')}${stat('对照策略组',num(plan.control),'计划分配比例 '+pct(plan.controlShare,0))}${stat('总样本量',num(plan.total),'双侧 5% · 功效 80%')}</div><p>规划基线 ${pct(plan.p0,3)} → 预期可检测 ${pct(plan.p1,3)}；MDE ${num(plan.diff*100,3)} 个百分点。${plan.days?`按输入的日均合格新用户数，招募约 ${plan.days} 天，之后还需完成观察窗口。`:'未填写合格新用户流量，不估算实验天数。'}</p><div class="stacked"><span class="baseline" style="width:${plan.controlShare*100}%"></span><span class="increment" style="width:${(1-plan.controlShare)*100}%"></span></div><p class="muted">对照 ${pct(plan.controlShare,0)} / 候选 ${pct(1-plan.controlShare,0)}。基于独立用户、二项转化和固定样本检验的大样本近似，不计流失与聚类；不适用于直接验证货币指标。</p>`;}
function planWorkbench(s){const g=currentGroup(s),p=g.plan;return `<section class="panel"><span class="eyebrow">EXPERIMENT DESIGN</span><h3>下一轮实验设计卡</h3><p>以下内容是学员事前规划，不是案例已发生的事实。建议比较一个候选策略与现行策略，所有合格用户先随机分组，再实施策略。</p><form id="plan-form"><div class="form-grid">${[['hypothesis','处理 / 对照与待验证假设','例如明确写出两组策略、希望改善的结果及依据'],['unit','随机单元',''],['primary','主指标定义',''],['window','观察窗口与招募规则','请填写入组后观察多久、何时停止招募'],['guardrail','执行与经营护栏','分流、追踪质量、成本、用户体验及阈值'],['decision','推广 / 维持 / 回滚规则','样本达到且观察完成后，如何结合区间和经济性决策']].map(([key,label,placeholder])=>`<label class="${['hypothesis','decision'].includes(key)?'span-2':''}">${label}<textarea name="${key}" rows="2" placeholder="${placeholder}" required>${esc(p[key])}</textarea></label>`).join('')}</div><h4>为主转化率指标规划样本量</h4><div class="form-grid"><label>比较基线<select name="baseline"><option value="commercial"${selected(p.baseline||'commercial','commercial')}>现行商业策略（推荐用于策略优化）</option><option value="psa"${selected(p.baseline,'psa')}>PSA（用于重新测量广告增量）</option></select></label><label>最小有意义效果 · 百分点<input type="number" name="mdePP" min="0.001" max="99" step="any" value="${esc(p.mdePP)}" placeholder="团队自行确定，不预填假数据"></label><label>对照比例<select name="controlShare">${[['0.5','50%'],['0.2','20%'],['0.04','4%（原案例比例，仅供权衡）']].map(([v,l])=>`<option value="${v}"${selected(v,p.controlShare)}>${l}</option>`).join('')}</select></label><label>日均合格新用户 · 可选<input type="number" name="dailyUsers" min="1" step="1" value="${esc(p.dailyUsers)}" placeholder="没有流量预测就留空"></label></div><div id="planner-result">${plannerResult(s)}</div><div class="form-footer"><span>文字与计划输入自动保存在本组</span><button type="submit" class="primary">检查实验计划</button></div></form></section>`;}
function exercise(s,l){const g=currentGroup(s),n=g.notes[l.id]||{},status=submissionState(g,l.id,s.meta?.hash),history=g.submissions[l.id]||[];return `<section class="panel exercise" id="exercise"><div class="panel-heading"><div><span class="eyebrow">TEAM EVIDENCE / 可选练习</span><h3>${esc(g.name)}的第 ${l.n} 题记录</h3></div><span class="pill evidence-state" data-question="${l.id}">${stateLabel[status]}</span></div><p>${l.evidence}</p><div class="form-grid"><label>独立初判<textarea data-note="initial" data-question="${l.id}" rows="3" placeholder="在讨论前，你如何判断？">${esc(n.initial)}</textarea></label><label>数据证据与跨题引用<textarea data-note="evidence" data-question="${l.id}" rows="3" placeholder="记录公式、数值、区间与来源。前题证据会在提交时绑定。">${esc(n.evidence)}</textarea></label><label class="span-2">本组结论与限制<textarea data-note="answer" data-question="${l.id}" rows="3" placeholder="用一段话支持经营判断，并写出证据边界。">${esc(n.answer)}</textarea></label></div><div class="form-footer"><span>自动本地保存 · 修改前题后，后题证据需重新提交；文字保留。</span><button class="primary" data-action="submit-evidence" data-question="${l.id}">提交本题证据</button></div><details><summary>历史提交与引用（${history.length} 版）</summary>${history.slice().reverse().map((h,i)=>`<div class="history"><b>版本 ${history.length-i} · ${esc(h.at)}</b><p>${esc(h.notes?.answer)}</p><small>数据 ${esc(h.dataHash?.slice(0,16))}… · 引用 ${esc(Object.keys(h.references||{}).join('、')||'无前题')}</small></div>`).join('')||'<p>还没有提交记录。</p>'}</details></section>`;}
export function lessonView(s,id){const l=lessons.find(x=>x.id===id);const visual=id==='q1'?referenceMetrics(s)+metricsWorkbench(s):id==='q2'?panel('从原始分组到因果结论',q2Answer(s)):id==='q3'?economicsWorkbench(s):`${panel('先探索，再提出实验假设',`<div class="panel-heading"><p>这些是投放后变量的描述性切片，不是随机化策略。</p><label>探索维度<select id="exploration-dimension"><option value="frequency"${selected(s.dimension,'frequency')}>累计曝光频次</option><option value="day"${selected(s.dimension,'day')}>曝光最多的星期</option><option value="hour"${selected(s.dimension,'hour')}>曝光最多的小时</option></select></label></div><div id="exploration-chart">${explorationChart(s.summary,s.dimension)}</div>`)}${planWorkbench(s)}`;
 return `${pageHead(`QUESTION ${l.n} / ${l.time} MIN`,l.title,l.question)}<div class="lesson-context"><span>业务背景</span><p>${l.context}</p></div><section class="panel"><div class="panel-heading"><h3>本题需要完成什么</h3><span class="pill">建议小组讨论 · ${l.time} 分钟</span></div><div class="three-col tasks">${l.tasks.map(([t,b],i)=>`<article><span class="step-no">${i+1}</span><h4>${t}</h4><p>${b}</p></article>`).join('')}</div><p class="deliverable"><b>本题交付</b> ${l.deliverable}</p><p class="source-note">案例依据：${l.origin} ${link(sources.caseMirror,'正文镜像')}</p></section>
 <section class="answer-intro"><span class="eyebrow">WORKED ANSWER / 完整参考答案</span><h2>${id==='q1'?'用指标约定因果问题。':id==='q2'?'比较概率，给出不确定性。':id==='q3'?'只为广告带来的增量记功。':'先随机分配策略，再观察结果。'}</h2><p>${l.answer}</p></section><div class="answer-steps">${l.steps.map(([title,text],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${text}</p></div></article>`).join('')}</div>
 ${visual}${note(`<b>结论边界</b><br>${l.boundary}`,'warning')}${panel('进阶讨论',`<p>${l.challenge}</p>`)}${exercise(s,l)}<a class="next-card" href="#${id==='q4'?'groups':'q'+(Number(id.slice(1))+1)}"><span>${id==='q4'?'最后 10 分钟 · 小组答辩':'继续下一题'}</span><strong>${id==='q4'?'用证据回应另一组的质疑':lessons[Number(id.slice(1))].short} ↗</strong></a>`;
}
export function groupsView(s){const g=currentGroup(s);return `${pageHead('TEAM WORKSPACE / 分组讨论与答辩','让不同的口径，摆在一起讨论。','每组独立保存指标、初判、证据和实验计划。可在本机切换小组，或导入其他设备导出的文件进行课堂对比。')}
 ${panel('当前小组',`<div class="button-row"><label>切换小组<select id="group-select">${s.groups.map(x=>`<option value="${esc(x.id)}"${selected(x.id,g.id)}>${esc(x.name)}</option>`).join('')}</select></label><form id="group-form" class="inline-form"><label>新小组名称<input name="name" required maxlength="60" placeholder="例如第三组"></label><button class="primary" type="submit">创建小组</button></form></div><div class="button-row"><button data-action="export-groups">导出全部小组 JSON ↓</button><button data-action="import-groups">导入其他小组（新增副本）</button><button data-action="export-report">导出当前小组报告 ↓</button></div><p class="muted">草稿在当前浏览器本地保存；点击导出时生成本机文件，没有多人实时同步。导入始终新增小组副本，不覆盖已有记录。Air France 使用独立存储，旧笔记仍可在参考入口读取。</p>`)}
 ${panel('小组指标体系对比',`<div class="group-comparison">${s.groups.map(x=>`<article><h3>${esc(x.name)}</h3>${x.metrics.map(m=>`<div><b>${esc(m.name)}</b><span class="pill">${esc(m.role)}</span><code>${esc(m.formula)}</code><small>${populationLabel(m.population)} · ${esc(m.window)} · ${esc(m.unit)}</small><p>${esc(m.meaning)}</p></div>`).join('')||'<p>尚未定义指标。</p>'}<p class="muted">定义历史：${x.metricHistory?.length||0} 个版本</p></article>`).join('')}</div>`)}
 ${panel('当前小组的证据链',`<div class="mission-chain compact">${lessons.map(l=>`<a href="#${l.id}"><span>${l.n}</span><h4>${l.short}</h4><small>${stateLabel[submissionState(g,l.id,s.meta?.hash)]}</small></a>`).join('')}</div>`)}
 ${panel('最后 10 分钟：交叉答辩',`<ol class="debate"><li><b>2 分钟｜主张</b> 每组用一句话回答“是否继续投”，同时说出条件。</li><li><b>4 分钟｜质疑</b> 另一组检查分母、PSA 反事实、成本范围与区间；指出一个超出数据的推断。</li><li><b>3 分钟｜修订</b> 调整指标或结论，保留原文与版本，重新提交受影响的证据。</li><li><b>1 分钟｜收束</b> 说明下一轮实验会怎样改变经营决策。</li></ol><p>评阅建议：口径清楚 25%、因果与不确定性 30%、经营核算 25%、实验可执行性 20%。这些是本课教学评分建议，不是原案例标准评分。</p>`)}<a href="/downloads/course-guide.md" download>下载四题完整讲义 ↓</a>`;}
export function sourcesView(){return `${pageHead('SOURCES / 可追溯的教学材料','案例有出处，计算可复现。','教学案例可以经过匿名化或修改。本项目使用既有材料，区分官方信息、公开镜像、计算结果和学员假设。')}
 ${panel('来源分层',`<div class="source-list"><article><span class="pill">官方</span><h3>Berkeley Haas · B5894</h3><p>Zsolt Katona、Brian Bell，2017。官方页面确认了用户随机对照设计及同名配套 CSV。</p>${link(sources.official,'HBR 官方案例页')} · ${link(sources.haas,'Haas 案例介绍')}</article><article><span class="pill">课程使用记录</span><h3>作者的 Marketing Core 课程</h3><p>Berkeley Haas EWMBA206，Fall 2021。课程大纲列有 Rocket Fuel 小组案例分析，并安排 A/B Testing 讨论。</p>${link(sources.course,'查看作者课程大纲')}</article><article><span class="pill">公开镜像 · 未认证官方原件</span><h3>数据与正文核对</h3><p>CSV 来自公开 GitHub 镜像，固定提交 ${caseFile.commit}。案例参数、字段释义与题目主题根据正文镜像核对。原文注明部分名称与数值为保密而修改。</p>${link(sources.dataMirror,'数据镜像固定版本')} · ${link(sources.caseMirror,'正文镜像')}</article></div>`)}
 ${panel('文件身份与复现',`<p>文件：${caseFile.filename} · ${num(caseFile.bytes)} 字节 · ${num(caseFile.rows)} 条用户记录 · 6 列。</p><code class="hash">SHA-256 ${caseFile.sha256}</code><p>换环境启动并自动准备数据：<code>npm start</code><br>单独下载：<code>npm run data:download</code><br>检查数据是否就绪：<code>npm run data:check</code><br>重算数据检查：<code>npm run data:inspect</code><br>执行计算测试：<code>npm test</code></p><p>原始与派生明细仅保存在本机 data/private，由本地白名单端点提供。仅有静态文件时，可在数据页从固定镜像加载到浏览器内存或手动导入。静态网站中没有嵌入原始或派生记录，不向 Sites 发布。</p>`)}
 ${panel('统计方法',`<p>单组比例使用 Wilson 95% 区间；两组差使用 Newcombe 独立两比例区间。只对用户级二项结果作这一推断，不自动给任意自定义公式附加区间。</p>${link(sources.ci,'statsmodels 区间方法')}<p>实验规划使用双侧 α = 0.05、功效 80% 的大样本比例差近似，按用户独立、固定样本计算。输入 MDE 与未来流量是计划参数。</p>${link(sources.power,'statsmodels 样本量方法')}`)}
 ${panel('教学改编与旧版材料',`<p>四题的中文编排、可视化推导与参考答案是本项目的教学改编，不是出版方官方答案。网站提供摘要、公式和来源链接，不分发完整付费案例正文。</p><p>Air France KEL319 / KEL321 已独立保留，包括旧网站、课程资料与数据入口。两套案例不合并成同一家企业的经营数据。</p><a href="/reference/air-france/">打开 Air France 旧版 ↗</a><div class="button-row"><a class="button" href="/downloads/course-guide.md" download>问题与答案讲义 ↓</a><a class="button" href="/downloads/teaching-guide.md" download>教师引导手册 ↓</a></div>`)}`;}
export function renderPage(s,page){if(page==='story')return storyView(s);if(page==='mission')return missionView();if(page==='data')return dataView(s);if(page==='groups')return groupsView(s);if(page==='sources')return sourcesView();if(lessons.some(l=>l.id===page))return lessonView(s,page);return storyView(s);}
